#include <iostream>

bool SafeMultiply(int a, int b, int& result);

int main()
{
    int a, b;
    while (std::cin >> a >> b)
    {
        int result = 123456789;
        if (SafeMultiply(a, b, result))
        {
            std::cout << "ok " << result << "\n";
        }
        else
        {
            std::cout << "overflow " << result << "\n";
        }
    }
    return 0;
}

