"""Random operand pairs at several magnitudes, including values clustered
around sqrt(INT_MAX) and the int limits."""

INTERESTING = [0, 1, -1, 2, -2, 46340, 46341, -46340, -46341, 65536, -65536,
               32768, -32768, 2147483647, -2147483648, 1073741824, -1073741824]


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    lines = []
    for _ in range(6):
        pick = rng.random()
        if pick < 0.4:
            a, b = rng.choice(INTERESTING), rng.choice(INTERESTING)
        elif pick < 0.7:
            a, b = rng.randint(-100000, 100000), rng.randint(-100000, 100000)
        else:
            a, b = rng.randint(-2**31, 2**31 - 1), rng.randint(-50, 50)
        lines.append("%d %d" % (a, b))
    return {"name": "six operand pairs #%d" % index,
            "stdin": "\n".join(lines) + "\n"}
